-- 0071_tallaby_classic_template_v3.sql (storefront templates, 2026-10-19)
--
-- Storefront template "Tallaby Classic" v3, generated from
-- packages/store-sections/src/templates/classic/ by
-- `pnpm --filter @workspace/store-sections template:sql tallaby-classic 0071_tallaby_classic_template_v3.sql`.
-- A test checks this file matches the package. Adds or updates the template row as
-- THE default (what new stores start from; any other default is cleared)
-- and makes this version current. Stores' drafts and live sites are not
-- touched.
--
-- Idempotent.

UPDATE templates SET is_default = false, updated_at = now()
WHERE is_default AND key <> 'tallaby-classic';

INSERT INTO templates (key, name, description, category, sort_order, is_default, is_active, is_premium)
VALUES (
  'tallaby-classic',
  '{"ar":"طلبي الكلاسيكي","en":"Tallaby Classic"}'::jsonb,
  '{"ar":"القالب الافتراضي: بسيط وعصري، بألوان هادئة وكروت مدوّرة. ست صفحات جاهزة لأي نوع متجر.","en":"The default template: simple and modern, with calm colours and rounded cards. Six ready pages for any kind of store."}'::jsonb,
  'general',
  0,
  true,
  true,
  false
)
ON CONFLICT (key) DO UPDATE SET
  name = EXCLUDED.name,
  description = EXCLUDED.description,
  category = EXCLUDED.category,
  sort_order = EXCLUDED.sort_order,
  is_default = true,
  is_active = true,
  is_premium = false,
  updated_at = now();

