-- template-config:end
  'Tallaby Classic v3: rebuilt as element trees (header, 9 home sections, About, Contact, FAQ, Privacy, Terms, footer)'
FROM templates t
WHERE t.key = 'tallaby-classic'
ON CONFLICT (template_id, version) DO NOTHING;

UPDATE templates t SET current_version_id = v.id, updated_at = now()
FROM template_versions v
WHERE t.key = 'tallaby-classic' AND v.template_id = t.id AND v.version = 3
  AND t.current_version_id IS DISTINCT FROM v.id;

